from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 7))
    # small values, few colors to force duplicates; include extremes scaled down
    pairs = draw(st.lists(
        st.tuples(st.integers(1, 10), st.integers(1, 4)),
        min_size=n, max_size=n))
    lines = [str(n)] + [f"{a} {c}" for a, c in pairs]
    return "\n".join(lines) + "\n"

def validate(inp):
    try:
        lines = inp.strip("\n").split("\n")
        n = int(lines[0])
        if not (1 <= n <= 2 * 10**5):
            return False
        if len(lines) != n + 1:
            return False
        for i in range(1, n + 1):
            parts = lines[i].split(" ")
            if len(parts) != 2:
                return False
            a, c = int(parts[0]), int(parts[1])
            if not (1 <= a <= 10**9 and 1 <= c <= 10**9):
                return False
        return True
    except Exception:
        return False

def ref(inp):
    lines = inp.strip("\n").split("\n")
    n = int(lines[0])
    beans = []
    for i in range(1, n + 1):
        a, c = map(int, lines[i].split())
        beans.append((a, c))
    # literal definition: for each color, minimum deliciousness among its beans;
    # then maximize over colors
    colors = set(c for _, c in beans)
    best = None
    for col in colors:
        m = min(a for a, c in beans if c == col)
        if best is None or m > best:
            best = m
    return str(best)
